do $patch$
declare definition text;
begin
 select pg_get_functiondef('public.quick_match_action_v1(uuid,text,jsonb)'::regprocedure) into definition;
 if strpos(definition,'where tournament_id=t.id and player_id=incoming and present and is_substitute and coalesce(registration_status,''confirmed'')<>''waitlist'') then raise exception ''Choisis un remplaçant déclaré et présent''')=0 or strpos(definition,'if exists(select 1 from public.match_player_assignments a join public.matches x on x.id=a.match_id where a.player_id=incoming and a.team_id is not null and x.tournament_id=t.id and (x.id=m.id or (m.status<>''finished'' and x.status<>''finished''))) then raise exception ''Ce remplaçant joue déjà dans un match en cours''; end if;')=0 then raise exception 'Unexpected quick match definition'; end if;
 definition:=replace(replace(definition,'where tournament_id=t.id and player_id=incoming and present and is_substitute and coalesce(registration_status,''confirmed'')<>''waitlist'') then raise exception ''Choisis un remplaçant déclaré et présent''','where tournament_id=t.id and player_id=incoming and present and coalesce(registration_status,''confirmed'')<>''waitlist'') then raise exception ''Choisis un joueur présent du tournoi'''),'if exists(select 1 from public.match_player_assignments a join public.matches x on x.id=a.match_id where a.player_id=incoming and a.team_id is not null and x.tournament_id=t.id and (x.id=m.id or (m.status<>''finished'' and x.status<>''finished''))) then raise exception ''Ce remplaçant joue déjà dans un match en cours''; end if;','if exists(select 1 from public.matches x where x.tournament_id=t.id and (x.id=m.id or (m.status<>''finished'' and x.status in (''live'',''playing'',''in_progress''))) and (exists(select 1 from public.match_player_assignments a where a.match_id=x.id and a.player_id=incoming and a.team_id is not null) or (not exists(select 1 from public.match_player_assignments a where a.match_id=x.id) and exists(select 1 from public.team_players a where a.team_id in (x.home_team_id,x.away_team_id) and a.player_id=incoming)))) then raise exception ''Ce joueur joue déjà dans ce match ou un match en cours''; end if;');
 execute definition;
end $patch$;
